/**
 * 私密笔记系统 - Cloudflare Worker (单文件, ES Module, 零 npm 依赖)
 * 部署: notes.19901980.xyz
 *
 * 绑定 (env):
 *   NOTES_DB            D1 数据库 (必需, 唯一存储: 笔记 + 图片 base64 + 审计)
 *   NOTES_PASSWORD      网页登录密码 (Secret, 可选; 不设则默认 admin)
 *   NOTES_SESSION_SECRET 会话 HMAC 密钥 (Secret, 可选; 不设则默认 admin)
 *   NOTES_API_KEY       API 的 Bearer 密钥 (Secret, 可选; 不设则默认 admin。
 *                       单用户系统, 网页密码即 API 密钥; 在设置页改过密码后以
 *                       D1 password_hash 为准, 旧密钥立刻失效)
 *   默认账号: 登录密码 admin / API 密钥 admin (第一次登录后请立即去设置页改密码)
 *
 * 存储说明 (2026-11-20 修订, 用户决定不用 R2):
 *   全部只用 D1 顶着。文字为主、图片很少。图片存 media_data 表 (base64),
 *   客户端上传前先压缩: 最长边 1600px、JPEG 质量 0.8、目标 <800KB、硬上限 1.5MB。
 *   视频不做: D1 单行上限 2MB, 视频放不下, 上传接口只接受图片, 拒绝视频并明示。
 */

const VERSION = '1.0.0';
const SESSION_COOKIE = 'notes_session';
const SESSION_MAX_AGE = 30 * 24 * 3600; // 30 天
const MAX_IMAGE_BYTES = 1536 * 1024;   // 图片硬上限 1.5MB (base64 后约 2MB, 贴近 D1 单行上限, 见 TESTS.md)
const TARGET_IMAGE_BYTES = 800 * 1024; // 客户端压缩目标 <800KB

const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS notes (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL DEFAULT '',
  content TEXT NOT NULL DEFAULT '',
  tags TEXT NOT NULL DEFAULT '[]',
  pinned INTEGER NOT NULL DEFAULT 0,
  trashed INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'published',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  cover_key TEXT,
  category TEXT
);
CREATE TABLE IF NOT EXISTS media_meta (
  id TEXT PRIMARY KEY,
  note_id TEXT,
  key TEXT NOT NULL,
  filename TEXT NOT NULL DEFAULT '',
  mime TEXT NOT NULL DEFAULT '',
  size INTEGER NOT NULL DEFAULT 0,
  kind TEXT NOT NULL DEFAULT 'image',
  backend TEXT NOT NULL DEFAULT 'r2',
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS media_data (
  key TEXT PRIMARY KEY,
  data TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS audit_log (
  id TEXT PRIMARY KEY,
  actor TEXT NOT NULL DEFAULT '',
  action TEXT NOT NULL DEFAULT '',
  target TEXT NOT NULL DEFAULT '',
  detail TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS categories (
  name TEXT PRIMARY KEY,
  created_at INTEGER NOT NULL,
  ord INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_notes_updated ON notes(updated_at);
CREATE INDEX IF NOT EXISTS idx_media_note ON media_meta(note_id);
`;

let schemaPromise = null;
function ensureSchema(env) {
  if (!schemaPromise) {
    // D1 的 exec() 只接受单条语句，多条写在一起会在真 D1 上抛错（本地桩没拦住，
    // 这就是 health 报 1101 的原因）。按分号拆成单条逐条执行。
    const stmts = SCHEMA_SQL.split(';').map((s) => s.trim()).filter(Boolean);
    schemaPromise = (async () => {
      for (const sql of stmts) await env.NOTES_DB.prepare(sql).run();
      // 老库迁移: 给已存在的 notes 表补 category 列 (已有则忽略)
      try { await env.NOTES_DB.prepare('ALTER TABLE notes ADD COLUMN category TEXT').run(); }
      catch (e) { if (!String(e && e.message || e).includes('duplicate column')) throw e; }
      try { await env.NOTES_DB.prepare('ALTER TABLE notes ADD COLUMN status TEXT NOT NULL DEFAULT \'published\'').run(); }
      catch (e) { if (!String(e && e.message || e).includes('duplicate column')) throw e; }
      try { await env.NOTES_DB.prepare('ALTER TABLE categories ADD COLUMN ord INTEGER NOT NULL DEFAULT 0').run(); }
      catch (e) { if (!String(e && e.message || e).includes('duplicate column')) throw e; }
    })().catch((e) => {
      schemaPromise = null;
      throw e;
    });
  }
  return schemaPromise;
}

/* ---------------- 通用工具 ---------------- */

function json(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8', ...extraHeaders },
  });
}
function ok(data, status = 200, extraHeaders = {}) {
  return json({ ok: true, data, error: null }, status, extraHeaders);
}
function fail(code, message, status = 400) {
  return json({ ok: false, data: null, error: { code, message } }, status);
}
function nowMs() { return Date.now(); }
function newId() { return crypto.randomUUID(); }

const B64URL = {
  encode(buf) {
    const bytes = buf instanceof ArrayBuffer ? new Uint8Array(buf) : buf;
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  },
  decode(str) {
    const s = str.replace(/-/g, '+').replace(/_/g, '/');
    const bin = atob(s);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  },
};

async function sha256Hex(text) {
  const d = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, '0')).join('');
}
async function hmacB64(secret, text) {
  const key = await crypto.subtle.importKey(
    'raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(text));
  return B64URL.encode(sig);
}
function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

/* ---------------- 会话与鉴权 ---------------- */

async function signSession(secret, exp) {
  const sig = await hmacB64(secret, 'notes-session:' + exp);
  return exp + '.' + sig;
}
async function verifySession(secret, token) {
  if (!token || !secret) return false;
  const parts = token.split('.');
  if (parts.length !== 2) return false;
  const exp = Number(parts[0]);
  if (!Number.isFinite(exp) || exp * 1000 < Date.now()) return false;
  const expect = await hmacB64(secret, 'notes-session:' + exp);
  return safeEqual(parts[1], expect);
}
function getCookie(request, name) {
  const h = request.headers.get('Cookie') || '';
  for (const part of h.split(';')) {
    const [k, ...v] = part.trim().split('=');
    if (k === name) return decodeURIComponent(v.join('='));
  }
  return null;
}
// Docker 版: 局域网常走明文 HTTP, Secure 只在 HTTPS 访问时才加,
// 否则浏览器在明文 HTTP 下不回传 Cookie、登录后立刻掉线。
// (Cloudflare 版一直是 HTTPS, 不用改。)
function sessionCookieHeader(token, maxAge = SESSION_MAX_AGE, secure = true) {
  var h = SESSION_COOKIE + '=' + encodeURIComponent(token) +
    '; HttpOnly;' + (secure ? ' Secure;' : '') + ' SameSite=Lax; Path=/';
  if (maxAge === null || maxAge === undefined) return h; // 会话 Cookie, 浏览器关闭即失效
  return h + '; Max-Age=' + maxAge;
}

async function authenticate(request, env) {
  const auth = request.headers.get('Authorization') || '';
  if (auth.startsWith('Bearer ')) {
    const presented = await sha256Hex(auth.slice(7).trim());
    // 登录密码 = API 密钥 (同一串): 以 D1 settings 里的 password_hash 为准
    // (用户在设置页改过密码就以新密码为准, 网页端改密码 API 立刻跟着变);
    // 没改过密码时回退到 Secret NOTES_API_KEY / NOTES_PASSWORD。
    for (const h of await getApiPasswordHashes(env)) {
      if (safeEqual(presented, h)) return { authed: true, actor: 'api' };
    }
  }
  const token = getCookie(request, SESSION_COOKIE);
  if (token && await verifySession(env.NOTES_SESSION_SECRET || env.NOTES_PASSWORD || 'admin', token)) {
    return { authed: true, actor: 'web' };
  }
  return { authed: false, actor: null };
}

/* ---------------- D1 小助手 ---------------- */

async function dbAll(env, sql, params = []) {
  const r = await env.NOTES_DB.prepare(sql).bind(...params).all();
  return r.results || [];
}
async function dbGet(env, sql, params = []) {
  const r = await env.NOTES_DB.prepare(sql).bind(...params).first();
  return r || null;
}
async function dbRun(env, sql, params = []) {
  return env.NOTES_DB.prepare(sql).bind(...params).run();
}
async function audit(env, actor, action, target, detail = '') {
  try {
    await dbRun(env,
      'INSERT INTO audit_log (id, actor, action, target, detail, created_at) VALUES (?, ?, ?, ?, ?, ?)',
      [newId(), actor, action, target || '', String(detail).slice(0, 500), nowMs()]);
  } catch (_) { /* 审计失败不影响主操作 */ }
}

/* ---------------- 设置与备份 (网页设置页、REST、MCP 共用) ---------------- */

// 网页登录密码 = API 密钥 (同一串, 单用户系统): D1 settings 里的 password_hash
// 为准 (用户在设置页改过密码就以新密码为准, 旧密码立刻失效); 没改过则回退到
// Secret NOTES_PASSWORD / NOTES_API_KEY。网页端改密码, 登录与 API 一起生效。
// API 侧以 D1 为准的口令哈希 (没改过密码时回退到 Secret)。
async function getApiPasswordHashes(env) {
  const row = await dbGet(env, 'SELECT value FROM settings WHERE key = ?', ['password_hash']);
  if (row) return [row.value];
  const out = [];
  for (const s of [env.NOTES_API_KEY, env.NOTES_PASSWORD, 'admin']) {
    if (s) out.push(await sha256Hex(s));
  }
  return out;
}
async function getWebPasswordHash(env) {
  const row = await dbGet(env, 'SELECT value FROM settings WHERE key = ?', ['password_hash']);
  if (row) return row.value;
  return env.NOTES_PASSWORD ? await sha256Hex(env.NOTES_PASSWORD) : await sha256Hex('admin');
}
async function setWebPassword(env, password) {
  const hash = await sha256Hex(password);
  await dbRun(env,
    'INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value',
    ['password_hash', hash]);
  return true;
}

async function exportBackup(env) {
  const notes = await dbAll(env,
    'SELECT id, title, content, tags, category, pinned, trashed, status, created_at, updated_at, cover_key FROM notes ORDER BY updated_at DESC', []);
  const out = [];
  for (const r of notes) {
    const n = rowToNote(r);
    const metas = await dbAll(env, 'SELECT * FROM media_meta WHERE note_id = ? ORDER BY created_at DESC', [r.id]);
    n.media = [];
    for (const m of metas) {
      const d = await dbGet(env, 'SELECT data FROM media_data WHERE key = ?', [m.id]);
      if (d) n.media.push({ id: m.id, filename: m.filename, mime: m.mime, data: d.data });
    }
    out.push(n);
  }
  return { version: 1, app: 'notes', exported_at: new Date().toISOString(), notes: out };
}

async function importBackup(env, backup, actor) {
  if (!backup || !Array.isArray(backup.notes)) {
    return { error: { code: 'bad_backup', message: '备份文件不对: 里面没有 notes 列表', status: 400 } };
  }
  if (backup.notes.length > 1000) {
    return { error: { code: 'backup_too_large', message: '一次最多导入 1000 条笔记', status: 400 } };
  }
  let created = 0, updated = 0, media = 0;
  for (const nb of backup.notes) {
    if (!nb || typeof nb !== 'object' || !nb.id) continue;
    const cur = await getNoteRow(env, nb.id);
    const tags = parseTags(nb.tags);
    const t = nowMs();
    if (cur) {
      await dbRun(env,
        'UPDATE notes SET title = ?, content = ?, tags = ?, category = ?, pinned = ?, trashed = ?, status = ?, updated_at = ?, cover_key = ? WHERE id = ?',
        [String(nb.title || '').slice(0, 200), String(nb.content || ''), JSON.stringify(tags),
         String(nb.category || '').trim().slice(0, 50) || null,
         nb.pinned ? 1 : 0, nb.trashed ? 1 : 0, nb.status === 'draft' ? 'draft' : 'published', typeof nb.updated_at === 'number' ? nb.updated_at : t,
         nb.cover_key || null, nb.id]);
      updated++;
    } else {
      await dbRun(env,
        'INSERT INTO notes (id, title, content, tags, category, pinned, trashed, status, created_at, updated_at, cover_key) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [nb.id, String(nb.title || '').slice(0, 200), String(nb.content || ''), JSON.stringify(tags),
         String(nb.category || '').trim().slice(0, 50) || null,
         nb.pinned ? 1 : 0, nb.trashed ? 1 : 0, nb.status === 'draft' ? 'draft' : 'published',
         typeof nb.created_at === 'number' ? nb.created_at : t,
         typeof nb.updated_at === 'number' ? nb.updated_at : t, nb.cover_key || null]);
      created++;
    }
    if (Array.isArray(nb.media)) {
      for (const mm of nb.media) {
        if (!mm || !mm.id || !mm.data) continue;
        const approxSize = Math.floor(String(mm.data).length * 3 / 4);
        await dbRun(env,
          'INSERT INTO media_meta (id, note_id, key, filename, mime, size, kind, backend, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET note_id = excluded.note_id, filename = excluded.filename, mime = excluded.mime',
          [mm.id, nb.id, mm.id, String(mm.filename || 'image'), String(mm.mime || ''), approxSize, 'image', 'd1', t]);
        await dbRun(env,
          'INSERT INTO media_data (key, data) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET data = excluded.data',
          [mm.id, String(mm.data)]);
        media++;
      }
    }
  }
  await audit(env, actor, 'backup.import', '', 'created=' + created + ' updated=' + updated + ' media=' + media);
  return { imported: created + updated, created, updated, media };
}

function parseTags(raw) {
  if (Array.isArray(raw)) return [...new Set(raw.map((t) => String(t).trim()).filter(Boolean))].slice(0, 20);
  if (typeof raw === 'string') {
    try { const p = JSON.parse(raw); if (Array.isArray(p)) return parseTags(p); } catch (_) {}
    return raw.split(/[,，、\s]+/).map((t) => t.trim()).filter(Boolean).slice(0, 20);
  }
  return [];
}
function rowToNote(r) {
  if (!r) return null;
  let tags = [];
  try { tags = JSON.parse(r.tags || '[]'); } catch (_) { tags = []; }
  return {
    id: r.id, title: r.title || '', content: r.content || '', tags, category: r.category || null,
    pinned: !!r.pinned, trashed: !!r.trashed, status: r.status || 'published',
    created_at: r.created_at, updated_at: r.updated_at,
    cover_key: r.cover_key || null,
    cover_url: r.cover_key ? '/api/v1/media/' + r.cover_key : null,
  };
}
function snippet(content, n = 140) {
  const t = (content || '').replace(/[#>*`!\[\]()]/g, ' ').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n) + '…' : t;
}

/* ---------------- 笔记核心操作 (REST 与 MCP 共用) ---------------- */

async function listNotes(env, opts = {}) {
  const q = (opts.q || '').trim();
  const tag = (opts.tag || '').trim();
  const trashed = opts.trashed || '0'; // '0' | '1' | 'all'
  const limit = Math.min(Math.max(parseInt(opts.limit, 10) || 50, 1), 200);
  const offset = Math.max(parseInt(opts.offset, 10) || 0, 0);
  const where = [];
  const params = [];
  if (trashed === '1') where.push('trashed = 1');
  else if (trashed !== 'all') where.push('trashed = 0');
  if (opts.pinned === '1' || opts.pinned === true) where.push('pinned = 1');
  if (trashed !== '1') {
    if (opts.status === 'draft') where.push("status = 'draft'");
    else if (opts.status !== 'all') where.push("status = 'published'");
  }
  if (q) { where.push('(title LIKE ? OR content LIKE ?)'); params.push('%' + q + '%', '%' + q + '%'); }
  if (tag) { where.push('tags LIKE ?'); params.push('%"' + tag.replace(/"/g, '') + '"%'); }
  if (opts.category) { where.push('category = ?'); params.push(opts.category); }
  const whereSql = where.length ? 'WHERE ' + where.join(' AND ') : '';
  const totalRow = await dbGet(env, 'SELECT COUNT(*) AS n FROM notes ' + whereSql, params);
  const rows = await dbAll(env,
    'SELECT id, title, content, tags, category, pinned, trashed, status, created_at, updated_at, cover_key FROM notes ' +
    whereSql + ' ORDER BY pinned DESC, updated_at DESC LIMIT ? OFFSET ?',
    [...params, limit, offset]);
  const items = rows.map(rowToNote);
  if (opts.brief) items.forEach(function (it) { it.content = snippet(it.content); it.brief = true; });
  return { items, total: totalRow ? totalRow.n : 0, limit, offset };
}

async function createNote(env, input, actor) {
  const title = String(input.title || '').trim().slice(0, 200);
  const content = String(input.content || '');
  const tags = parseTags(input.tags);
  const category = String(input.category || '').trim().slice(0, 50) || null;
  const pinned = input.pinned ? 1 : 0;
  const status = input.status === 'draft' ? 'draft' : 'published';
  const t = nowMs();
  const id = newId();
  await dbRun(env,
    'INSERT INTO notes (id, title, content, tags, category, pinned, status, trashed, created_at, updated_at, cover_key) VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?, NULL)',
    [id, title, content, JSON.stringify(tags), category, pinned, status, t, t]);
  await audit(env, actor, 'note.create', id, title);
  return rowToNote(await dbGet(env, 'SELECT * FROM notes WHERE id = ?', [id]));
}

async function getNoteRow(env, id) {
  return dbGet(env, 'SELECT * FROM notes WHERE id = ?', [id]);
}

async function updateNote(env, id, input, actor) {
  const cur = await getNoteRow(env, id);
  if (!cur) return null;
  const sets = [];
  const params = [];
  if (input.title !== undefined) { sets.push('title = ?'); params.push(String(input.title).trim().slice(0, 200)); }
  if (input.content !== undefined) { sets.push('content = ?'); params.push(String(input.content)); }
  if (input.tags !== undefined) { sets.push('tags = ?'); params.push(JSON.stringify(parseTags(input.tags))); }
  if (input.category !== undefined) { sets.push('category = ?'); params.push(String(input.category || '').trim().slice(0, 50) || null); }
  if (input.pinned !== undefined) { sets.push('pinned = ?'); params.push(input.pinned ? 1 : 0); }
  if (input.status !== undefined) { sets.push('status = ?'); params.push(input.status === 'draft' ? 'draft' : 'published'); }
  if (input.cover_key !== undefined) { sets.push('cover_key = ?'); params.push(input.cover_key || null); }
  if (!sets.length) return rowToNote(cur);
  // 只改置顶不算重新发布: 不碰 updated_at, 发布时间保持原样
  var touch = ['title', 'content', 'tags', 'category', 'status', 'cover_key'].some(function(k) { return input[k] !== undefined; });
  if (touch) { sets.push('updated_at = ?'); params.push(nowMs()); }
  params.push(id);
  await dbRun(env, 'UPDATE notes SET ' + sets.join(', ') + ' WHERE id = ?', params);
  await audit(env, actor, 'note.update', id, '');
  return rowToNote(await getNoteRow(env, id));
}

async function setTrashed(env, id, trashed, actor) {
  const cur = await getNoteRow(env, id);
  if (!cur) return null;
  await dbRun(env, 'UPDATE notes SET trashed = ?, updated_at = ? WHERE id = ?', [trashed ? 1 : 0, nowMs(), id]);
  await audit(env, actor, trashed ? 'note.trash' : 'note.restore', id, '');
  return rowToNote(await getNoteRow(env, id));
}

async function deleteNoteMedia(env, noteId) {
  const metas = await dbAll(env, 'SELECT id FROM media_meta WHERE note_id = ?', [noteId]);
  for (const m of metas) {
    await dbRun(env, 'DELETE FROM media_data WHERE key = ?', [m.id]);
    await dbRun(env, 'DELETE FROM media_meta WHERE id = ?', [m.id]);
  }
  return metas.length;
}

async function hardDeleteNote(env, id, actor) {
  const cur = await getNoteRow(env, id);
  if (!cur) return false;
  await deleteNoteMedia(env, id);
  await dbRun(env, 'DELETE FROM notes WHERE id = ?', [id]);
  await audit(env, actor, 'note.delete_hard', id, cur.title || '');
  return true;
}

async function emptyTrash(env, actor) {
  const rows = await dbAll(env, 'SELECT id FROM notes WHERE trashed = 1', []);
  for (const r of rows) {
    await deleteNoteMedia(env, r.id);
    await dbRun(env, 'DELETE FROM notes WHERE id = ?', [r.id]);
  }
  await audit(env, actor, 'trash.empty', '', String(rows.length));
  return { deleted: rows.length };
}

async function listTags(env) {
  const rows = await dbAll(env, 'SELECT tags FROM notes WHERE trashed = 0 AND status = \'published\'', []);
  const counts = {};
  for (const r of rows) {
    for (const t of parseTags(r.tags)) counts[t] = (counts[t] || 0) + 1;
  }
  return Object.entries(counts)
    .map(([tag, count]) => ({ tag, count }))
    .sort((a, b) => b.count - a.count);
}

async function listCategories(env) {
  const rows = await dbAll(env, 'SELECT name FROM categories ORDER BY ord ASC, created_at ASC', []);
  return rows.map((r) => r.name);
}
async function addCategory(env, name, actor) {
  const n = String(name || '').trim().slice(0, 50);
  if (!n) return { error: { code: 'bad_name', message: '分类名不能为空', status: 400 } };
  await dbRun(env, 'INSERT OR IGNORE INTO categories (name, created_at, ord) VALUES (?, ?, (SELECT COALESCE(MAX(ord), -1) + 1 FROM categories))', [n, nowMs()]);
  await audit(env, actor, 'category.add', n, '');
  return { categories: await listCategories(env) };
}
async function deleteCategory(env, name, actor) {
  const n = String(name || '').trim();
  await dbRun(env, 'DELETE FROM categories WHERE name = ?', [n]);
  await dbRun(env, 'UPDATE notes SET category = NULL WHERE category = ?', [n]);
  await audit(env, actor, 'category.delete', n, '');
  return { categories: await listCategories(env) };
}
async function reorderCategories(env, order, actor) {
  const current = await listCategories(env);
  const names = Array.isArray(order) ? order.map((s) => String(s || '').trim()).filter(Boolean) : [];
  const wanted = names.filter((n) => current.indexOf(n) >= 0);
  const rest = current.filter((n) => wanted.indexOf(n) < 0);
  const finalOrder = wanted.concat(rest);
  for (let i = 0; i < finalOrder.length; i++) {
    await dbRun(env, 'UPDATE categories SET ord = ? WHERE name = ?', [i, finalOrder[i]]);
  }
  await audit(env, actor, 'category.reorder', finalOrder.join(','), '');
  return { categories: await listCategories(env) };
}

/* ---------------- 媒体 (仅 D1, 仅图片) ---------------- */

function sanitizeFilename(name) {
  return String(name || 'image').replace(/[^\w.\-]+/g, '_').slice(0, 80) || 'image';
}

async function uploadMedia(env, formData, actor) {
  const file = formData.get('file');
  const noteId = formData.get('note_id') ? String(formData.get('note_id')) : null;
  if (!file || typeof file === 'string' || !file.size) {
    return { error: { code: 'no_file', message: '没有收到文件, 请重新选择图片', status: 400 } };
  }
  const mime = file.type || '';
  if (mime.startsWith('video/')) {
    return { error: { code: 'video_not_supported', message: '视频不做了: D1 单行上限 2MB, 视频放不下, 只支持图片', status: 415 } };
  }
  if (!mime.startsWith('image/')) {
    return { error: { code: 'not_image', message: '只支持图片上传 (JPEG/PNG/WebP 等)', status: 415 } };
  }
  if (file.size > MAX_IMAGE_BYTES) {
    return { error: { code: 'image_too_large', message: '图片超过 1.5MB 硬上限, 请压缩到 800KB 以内再传 (上传前会自动压缩, 超了请换一张更小的图)', status: 413 } };
  }
  if (noteId) {
    const note = await getNoteRow(env, noteId);
    if (!note) return { error: { code: 'note_not_found', message: '笔记不存在', status: 404 } };
  }
  const buf = new Uint8Array(await file.arrayBuffer());
  let b64 = '';
  const CHUNK = 0x8000;
  for (let i = 0; i < buf.length; i += CHUNK) {
    b64 += String.fromCharCode.apply(null, buf.subarray(i, i + CHUNK));
  }
  b64 = btoa(b64);
  if (b64.length > 2000000) {
    return { error: { code: 'image_too_large', message: '图片转存后超过 D1 单行上限, 请再压缩小一点 (目标 800KB 以内)', status: 413 } };
  }
  const id = newId();
  const t = nowMs();
  const filename = sanitizeFilename(file.name);
  await dbRun(env,
    'INSERT INTO media_meta (id, note_id, key, filename, mime, size, kind, backend, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [id, noteId, id, filename, mime, file.size, 'image', 'd1', t]);
  await dbRun(env, 'INSERT INTO media_data (key, data) VALUES (?, ?)', [id, b64]);
  if (noteId) {
    const note = await getNoteRow(env, noteId);
    if (note && !note.cover_key) {
      await dbRun(env, 'UPDATE notes SET cover_key = ?, updated_at = ? WHERE id = ?', [id, t, noteId]);
    }
  }
  await audit(env, actor, 'media.upload', id, filename + ' (' + file.size + 'B, d1)');
  return { media: { id, key: id, note_id: noteId, filename, mime, size: file.size, kind: 'image', backend: 'd1', url: '/api/v1/media/' + id, created_at: t } };
}

async function serveMedia(env, id) {
  const meta = await dbGet(env, 'SELECT * FROM media_meta WHERE id = ?', [id]);
  if (!meta) return fail('media_not_found', '图片不存在', 404);
  const row = await dbGet(env, 'SELECT data FROM media_data WHERE key = ?', [id]);
  if (!row) return fail('media_not_found', '图片数据缺失', 404);
  const bin = atob(row.data);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return new Response(out, {
    status: 200,
    headers: {
      'Content-Type': meta.mime || 'image/jpeg',
      'Content-Length': String(out.length),
      'Cache-Control': 'private, max-age=86400',
    },
  });
}

async function deleteMedia(env, id, actor) {
  const meta = await dbGet(env, 'SELECT * FROM media_meta WHERE id = ?', [id]);
  if (!meta) return false;
  await dbRun(env, 'DELETE FROM media_data WHERE key = ?', [id]);
  await dbRun(env, 'DELETE FROM media_meta WHERE id = ?', [id]);
  await dbRun(env, 'UPDATE notes SET cover_key = NULL WHERE cover_key = ?', [id]);
  await audit(env, actor, 'media.delete', id, meta.filename || '');
  return true;
}

/* ---------------- REST /api/v1/ ---------------- */

async function readJsonBody(request) {
  try {
    const t = await request.text();
    if (!t.trim()) return {};
    return JSON.parse(t);
  } catch (_) { return null; }
}

async function handleApi(request, env, url) {
  const seg = url.pathname.split('/').filter(Boolean); // ['api','v1',...]
  const method = request.method;
  await ensureSchema(env);

  // 健康检查: 不需要登录
  if (seg[2] === 'health' && method === 'GET') {
    return ok({
      status: 'ok', version: VERSION, time: new Date().toISOString(),
      storage: 'd1-only',
      db: !!env.NOTES_DB,
      configured: { password: !!env.NOTES_PASSWORD, api_key: !!env.NOTES_API_KEY, session_secret: !!env.NOTES_SESSION_SECRET },
    });
  }

  // 登录 / 登出 / 当前会话
  if (seg[2] === 'auth' && seg[3] === 'login' && method === 'POST') {
    const expected = await getWebPasswordHash(env);
    if (!expected) return fail('not_configured', '服务端还没设置登录密码, 请先在 Worker 里设好密钥', 503);
    const body = await readJsonBody(request);
    if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
    const presented = await sha256Hex(String(body.password || ''));
    if (!safeEqual(presented, expected)) return fail('bad_password', '密码不对', 401);
    const remember = body.remember !== false; // 默认记住, 30 天免登录
    const exp = Math.floor(Date.now() / 1000) + (remember ? SESSION_MAX_AGE : 12 * 3600);
    const token = await signSession(env.NOTES_SESSION_SECRET || env.NOTES_PASSWORD || 'admin', exp);
    return ok({ actor: 'web', remember }, 200, { 'Set-Cookie': sessionCookieHeader(token, remember ? SESSION_MAX_AGE : null, new URL(request.url).protocol === 'https:') });
  }
  if (seg[2] === 'auth' && seg[3] === 'logout' && method === 'POST') {
    return ok({ logged_out: true }, 200, { 'Set-Cookie': sessionCookieHeader('', 0, new URL(request.url).protocol === 'https:') });
  }
  if (seg[2] === 'auth' && seg[3] === 'me' && method === 'GET') {
    const a = await authenticate(request, env);
    return ok({ authed: a.authed, actor: a.actor });
  }

  // 其余接口都需要登录 (Cookie 会话或 Bearer API Key)
  const auth = await authenticate(request, env);
  if (!auth.authed) return fail('unauthorized', '请先登录', 401);
  const actor = auth.actor;

  // 设置: 改密码 (不用旧密码, 已登录即有权限; 登录密码 = API 密钥, 改完两边一起生效, 旧密码立刻失效)
  if (seg[2] === 'settings' && seg[3] === 'password' && method === 'POST') {
    const body = await readJsonBody(request);
    if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
    const pw = String(body.password || '');
    if (pw.length < 4) return fail('bad_password', '新密码至少 4 位', 400);
    if (pw.length > 200) return fail('bad_password', '新密码太长', 400);
    await setWebPassword(env, pw);
    await audit(env, actor, 'settings.password_change', '', '');
    return ok({ changed: true });
  }

  // 备份: 导出全部笔记 (含回收站与图片) / 导入恢复 (按 id 覆盖)
  if (seg[2] === 'backup' && seg[3] === 'export' && method === 'GET') {
    return ok(await exportBackup(env));
  }
  if (seg[2] === 'backup' && seg[3] === 'import' && method === 'POST') {
    const body = await readJsonBody(request);
    if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
    const doc = body.backup || body;
    const r = await importBackup(env, doc, actor);
    if (r.error) return fail(r.error.code, r.error.message, r.error.status);
    return ok(r);
  }

  // 标签列表
  if (seg[2] === 'tags' && method === 'GET') return ok(await listTags(env));

  // 分类管理: 设置里添加/删除, 写文章时从已设分类里选
  if (seg[2] === 'categories' && !seg[3] && method === 'GET') return ok(await listCategories(env));
  if (seg[2] === 'categories' && !seg[3] && method === 'POST') {
    const body = await readJsonBody(request);
    if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
    const r = await addCategory(env, body.name, actor);
    if (r.error) return fail(r.error.code, r.error.message, r.error.status);
    return ok(r, 201);
  }
  if (seg[2] === 'categories' && seg[3] === 'reorder' && method === 'POST') {
    const body = await readJsonBody(request);
    if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
    return ok(await reorderCategories(env, body.order, actor));
  }
  if (seg[2] === 'categories' && seg[3] && method === 'DELETE') {
    return ok(await deleteCategory(env, decodeURIComponent(seg[3]), actor));
  }

  // 媒体上传 / 读取 / 删除
  if (seg[2] === 'media' && method === 'POST') {
    let form;
    try { form = await request.formData(); }
    catch (_) { return fail('bad_form', '请用 multipart/form-data 上传, 字段名 file', 400); }
    const r = await uploadMedia(env, form, actor);
    if (r.error) return fail(r.error.code, r.error.message, r.error.status);
    return ok(r.media, 201);
  }
  if (seg[2] === 'media' && seg[3] && method === 'GET') return serveMedia(env, seg[3]);
  if (seg[2] === 'media' && seg[3] && method === 'DELETE') {
    const done = await deleteMedia(env, seg[3], actor);
    if (!done) return fail('media_not_found', '图片不存在', 404);
    return ok({ deleted: true });
  }

  // 回收站: 一键清空 (全部彻底删除, 不能恢复)
  if (seg[2] === 'trash' && seg[3] === 'empty' && method === 'POST') {
    return ok(await emptyTrash(env, actor));
  }

  // 笔记集合
  if (seg[2] === 'notes' && !seg[3]) {
    if (method === 'GET') {
      const sp = url.searchParams;
      return ok(await listNotes(env, {
        q: sp.get('q') || '', tag: sp.get('tag') || '', category: sp.get('category') || '', trashed: sp.get('trashed') || '0',
        pinned: sp.get('pinned') || '', status: sp.get('status') || '', limit: sp.get('limit') || '50', offset: sp.get('offset') || '0',
        brief: sp.get('brief') === '1',
      }));
    }
    if (method === 'POST') {
      const body = await readJsonBody(request);
      if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
      return ok(await createNote(env, body, actor), 201);
    }
  }

  // 单条笔记
  if (seg[2] === 'notes' && seg[3]) {
    const id = seg[3];
    if (seg[4] === 'media' && method === 'GET') {
      const rows = await dbAll(env, 'SELECT * FROM media_meta WHERE note_id = ? ORDER BY created_at DESC', [id]);
      return ok(rows.map((m) => ({
        id: m.id, note_id: m.note_id, filename: m.filename, mime: m.mime,
        size: m.size, kind: m.kind, backend: m.backend,
        url: '/api/v1/media/' + m.id, created_at: m.created_at,
      })));
    }
    if (seg[4] === 'restore' && method === 'POST') {
      const n = await setTrashed(env, id, false, actor);
      if (!n) return fail('note_not_found', '笔记不存在', 404);
      return ok(n);
    }
    if (seg[4] === 'pin' && method === 'POST') {
      const body = await readJsonBody(request) || {};
      const n = await updateNote(env, id, { pinned: body.pinned !== false }, actor);
      if (!n) return fail('note_not_found', '笔记不存在', 404);
      return ok(n);
    }
    if (!seg[4] && method === 'GET') {
      const n = rowToNote(await getNoteRow(env, id));
      if (!n) return fail('note_not_found', '笔记不存在', 404);
      return ok(n);
    }
    if (!seg[4] && method === 'PUT') {
      const body = await readJsonBody(request);
      if (!body) return fail('bad_json', '请求体不是合法 JSON', 400);
      const n = await updateNote(env, id, body, actor);
      if (!n) return fail('note_not_found', '笔记不存在', 404);
      return ok(n);
    }
    if (!seg[4] && method === 'DELETE') {
      if (url.searchParams.get('hard') === 'true') {
        const done = await hardDeleteNote(env, id, actor);
        if (!done) return fail('note_not_found', '笔记不存在', 404);
        return ok({ deleted: true, hard: true });
      }
      const n = await setTrashed(env, id, true, actor);
      if (!n) return fail('note_not_found', '笔记不存在', 404);
      return ok(n);
    }
  }

  return fail('not_found', '接口不存在: ' + url.pathname, 404);
}

/* ---------------- MCP /mcp (Streamable HTTP, JSON-RPC) ---------------- */

const MCP_TOOLS = [
  { name: 'create_note', description: '新建一条笔记, 标题/正文 Markdown/标签/分类可选, status=draft 存为草稿 (默认已发布)', inputSchema: { type: 'object', properties: { title: { type: 'string' }, content: { type: 'string' }, tags: { type: 'array', items: { type: 'string' } }, category: { type: 'string' }, pinned: { type: 'boolean' }, status: { type: 'string' } } } },
  { name: 'list_notes', description: '按更新时间列出笔记 (默认只列已发布, 不含回收站与草稿), 返回摘要', inputSchema: { type: 'object', properties: { limit: { type: 'number' }, offset: { type: 'number' }, trashed: { type: 'string', description: "'0' 正常, '1' 回收站, 'all' 全部" }, category: { type: 'string' }, status: { type: 'string', description: "'published' 已发布 (默认), 'draft' 草稿, 'all' 全部" } } } },
  { name: 'search_notes', description: '全文搜索标题和正文, 默认只搜已发布, 可按标签/分类过滤', inputSchema: { type: 'object', properties: { q: { type: 'string' }, tag: { type: 'string' }, category: { type: 'string' }, limit: { type: 'number' }, status: { type: 'string' } }, required: ['q'] } },
  { name: 'get_note', description: '按 id 读取一条笔记的完整内容', inputSchema: { type: 'object', properties: { id: { type: 'string' } }, required: ['id'] } },
  { name: 'update_note', description: '修改一条笔记 (只传要改的字段)', inputSchema: { type: 'object', properties: { id: { type: 'string' }, title: { type: 'string' }, content: { type: 'string' }, tags: { type: 'array', items: { type: 'string' } }, category: { type: 'string' }, pinned: { type: 'boolean' }, status: { type: 'string' } }, required: ['id'] } },
  { name: 'publish_note', description: '把一篇草稿发布: 状态改成已发布, 之后出现在首页列表/分类/搜索里', inputSchema: { type: 'object', properties: { id: { type: 'string' } }, required: ['id'] } },
  { name: 'empty_trash', description: '一键清空回收站: 把回收站里的全部笔记彻底删除 (连图片一起删), 不能恢复, 返回删除条数', inputSchema: { type: 'object', properties: {} } },
  { name: 'delete_note', description: '删除一条笔记: 默认进回收站, hard=true 彻底删除 (连图片一起删)', inputSchema: { type: 'object', properties: { id: { type: 'string' }, hard: { type: 'boolean' } }, required: ['id'] } },
  { name: 'change_password', description: '修改密码 (登录密码 = API 密钥, 同一串), 不需要旧密码 (调用者已通过 Bearer 登录), 新密码立即生效, 登录与 API 一起变, 旧密码立刻失效', inputSchema: { type: 'object', properties: { password: { type: 'string' } }, required: ['password'] } },
  { name: 'export_backup', description: '导出全部笔记 (含回收站与图片) 为备份文档 JSON, 可保存或再导入恢复', inputSchema: { type: 'object', properties: {} } },
  { name: 'import_backup', description: '导入备份文档恢复笔记, 按 id 覆盖已有的同 id 笔记 (重复即覆盖), 也恢复图片', inputSchema: { type: 'object', properties: { backup: { type: 'object', description: 'export_backup 返回的备份文档' } }, required: ['backup'] } },
  { name: 'list_categories', description: '列出已设置的分类 (写文章时从这里面选)', inputSchema: { type: 'object', properties: {} } },
  { name: 'add_category', description: '添加一个分类', inputSchema: { type: 'object', properties: { name: { type: 'string' } }, required: ['name'] } },
  { name: 'delete_category', description: '删除一个分类, 已用该分类的笔记会变成无分类', inputSchema: { type: 'object', properties: { name: { type: 'string' } }, required: ['name'] } },
  { name: 'reorder_categories', description: '调整分类的显示顺序, 按给定顺序排列 (点 MYNOTE 的下拉框、长按主页的下拉框与写文章选分类都按这个顺序显示)', inputSchema: { type: 'object', properties: { order: { type: 'array', items: { type: 'string' } } }, required: ['order'] } },
];

async function mcpCallTool(env, name, args, actor) {
  args = args || {};
  switch (name) {
    case 'create_note': {
      const n = await createNote(env, args, actor);
      return { ok: true, data: n };
    }
    case 'list_notes': {
      const r = await listNotes(env, { limit: args.limit, offset: args.offset, trashed: args.trashed || '0', category: args.category, status: args.status });
      r.items = r.items.map((n) => ({ ...n, content: snippet(n.content, 200) }));
      return { ok: true, data: r };
    }
    case 'search_notes': {
      if (!args.q) return { ok: false, error: { code: 'missing_q', message: 'search_notes 需要 q 参数' } };
      const r = await listNotes(env, { q: args.q, tag: args.tag, category: args.category, limit: args.limit, status: args.status });
      r.items = r.items.map((n) => ({ ...n, content: snippet(n.content, 200) }));
      return { ok: true, data: r };
    }
    case 'get_note': {
      const n = rowToNote(await getNoteRow(env, args.id));
      if (!n) return { ok: false, error: { code: 'note_not_found', message: '笔记不存在' } };
      return { ok: true, data: n };
    }
    case 'update_note': {
      const n = await updateNote(env, args.id, args, actor);
      if (!n) return { ok: false, error: { code: 'note_not_found', message: '笔记不存在' } };
      return { ok: true, data: n };
    }
    case 'publish_note': {
      const n = await updateNote(env, args.id, { status: 'published' }, actor);
      if (!n) return { ok: false, error: { code: 'note_not_found', message: '笔记不存在' } };
      return { ok: true, data: n };
    }
    case 'delete_note': {
      if (args.hard) {
        const done = await hardDeleteNote(env, args.id, actor);
        if (!done) return { ok: false, error: { code: 'note_not_found', message: '笔记不存在' } };
        return { ok: true, data: { deleted: true, hard: true, id: args.id } };
      }
      const n = await setTrashed(env, args.id, true, actor);
      if (!n) return { ok: false, error: { code: 'note_not_found', message: '笔记不存在' } };
      return { ok: true, data: n };
    }
    case 'empty_trash': {
      return { ok: true, data: await emptyTrash(env, actor) };
    }
    case 'change_password': {
      const pw = String(args.password || '');
      if (pw.length < 4) return { ok: false, error: { code: 'bad_password', message: '新密码至少 4 位' } };
      if (pw.length > 200) return { ok: false, error: { code: 'bad_password', message: '新密码太长' } };
      await setWebPassword(env, pw);
      await audit(env, actor, 'settings.password_change', '', 'via mcp');
      return { ok: true, data: { changed: true } };
    }
    case 'export_backup': {
      return { ok: true, data: await exportBackup(env) };
    }
    case 'import_backup': {
      const doc = args.backup || args;
      const r = await importBackup(env, doc, actor);
      if (r.error) return { ok: false, error: r.error };
      return { ok: true, data: r };
    }
    case 'list_categories': {
      return { ok: true, data: await listCategories(env) };
    }
    case 'add_category': {
      const r = await addCategory(env, args.name, actor);
      if (r.error) return { ok: false, error: r.error };
      return { ok: true, data: r };
    }
    case 'delete_category': {
      return { ok: true, data: await deleteCategory(env, args.name, actor) };
    }
    case 'reorder_categories': {
      return { ok: true, data: await reorderCategories(env, args.order, actor) };
    }
    default:
      return { ok: false, error: { code: 'unknown_tool', message: '未知工具: ' + name } };
  }
}

function rpcError(id, code, message) {
  return json({ jsonrpc: '2.0', id: id === undefined ? null : id, error: { code, message } });
}
function rpcResult(id, result) {
  return json({ jsonrpc: '2.0', id: id === undefined ? null : id, result });
}

async function handleMcp(request, env) {
  await ensureSchema(env);
  if (request.method === 'GET') {
    return fail('method_not_allowed', 'MCP 只接受 POST (Streamable HTTP), 本服务不做 SSE 推送', 405);
  }
  if (request.method !== 'POST') return fail('method_not_allowed', '只支持 POST', 405);
  const auth = await authenticate(request, env);
  if (!auth.authed) return rpcError(null, -32001, '请先登录: 需要 Bearer NOTES_API_KEY 或网页登录 Cookie');
  let body;
  try { body = await request.json(); } catch (_) { return rpcError(null, -32700, '请求体不是合法 JSON'); }
  const requests = Array.isArray(body) ? body : [body];
  const responses = [];
  for (const req of requests) {
    const id = req.id;
    const method = req.method || '';
    const params = req.params || {};
    if (method.startsWith('notifications/')) continue; // 通知无需回包
    if (method === 'initialize') {
      responses.push({ jsonrpc: '2.0', id, result: {
        protocolVersion: params.protocolVersion || '2024-11-05',
        capabilities: { tools: {} },
        serverInfo: { name: 'notes-mcp', version: VERSION },
      } });
    } else if (method === 'ping') {
      responses.push({ jsonrpc: '2.0', id, result: {} });
    } else if (method === 'tools/list') {
      responses.push({ jsonrpc: '2.0', id, result: { tools: MCP_TOOLS } });
    } else if (method === 'tools/call') {
      const r = await mcpCallTool(env, params.name, params.arguments, auth.actor);
      if (r.ok) {
        responses.push({ jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: JSON.stringify(r) }], isError: false } });
      } else {
        responses.push({ jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: JSON.stringify(r) }], isError: true } });
      }
    } else {
      responses.push({ jsonrpc: '2.0', id, error: { code: -32601, message: '未知方法: ' + method } });
    }
  }
  if (!responses.length) return new Response(null, { status: 202 });
  if (!Array.isArray(body) && responses.length === 1) return json(responses[0]);
  return json(responses);
}

