/* ---------------- PWA 静态资源 ---------------- */

const MANIFEST = {
  name: '笔记',
  short_name: '笔记',
  description: '仅自己可见的笔记, 支持 Markdown 与图片',
  start_url: '/',
  display: 'standalone',
  background_color: '#0f172a',
  theme_color: '#0f172a',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png' },
  ],
};

// 真实 PNG 图标 (由 gen_icons.py 生成, inject_icons.py 在部署前把 base64 填进来)
const ICON_192_B64 = '';
const ICON_512_B64 = '';
const APPLE_ICON_B64 = '';
const FAVICON_ICO_B64 = '';

const SW_JS = "var CACHE='notes-shell-v53';var SHELL=['/','/manifest.json','/icon-192.png','/icon-512.png','/apple-touch-icon.png'];"
+ "self.addEventListener('install',function(e){e.waitUntil(caches.open(CACHE).then(function(c){return c.addAll(SHELL)}).then(function(){return self.skipWaiting()}))});"
+ "self.addEventListener('activate',function(e){e.waitUntil(caches.keys().then(function(ks){return Promise.all(ks.filter(function(k){return k!==CACHE}).map(function(k){return caches.delete(k)}))}).then(function(){return self.clients.claim()}))});"
+ "self.addEventListener('fetch',function(e){var u=new URL(e.request.url);"
+ "if(u.pathname.indexOf('/api/')===0){e.respondWith(fetch(e.request));return;}"
+ "if(e.request.method!=='GET'){e.respondWith(fetch(e.request));return;}"
+ "e.respondWith(caches.match(e.request).then(function(hit){var net=fetch(e.request).then(function(r){if(r.ok){var cp=r.clone();caches.open(CACHE).then(function(c){c.put(e.request,cp)})}return r}).catch(function(){return hit});return hit||net}))});";

function pngResponse(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, {
    status: 200,
    headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=31536000, immutable' },
  });
}

/* ---------------- 路由 ---------------- */

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    if (path === '/manifest.json') {
      return json(MANIFEST, 200, { 'Cache-Control': 'public, max-age=86400' });
    }
    if (path === '/icon-192.png') return pngResponse(ICON_192_B64);
    if (path === '/icon-512.png') return pngResponse(ICON_512_B64);
    if (path === '/apple-touch-icon.png') return pngResponse(APPLE_ICON_B64);
    if (path === '/sw.js') {
      return new Response(SW_JS, { status: 200, headers: { 'Content-Type': 'application/javascript; charset=utf-8', 'Cache-Control': 'no-cache' } });
    }
    if (path === '/favicon.ico') {
      const bin = atob(FAVICON_ICO_B64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return new Response(bytes, { status: 200, headers: { 'Content-Type': 'image/x-icon', 'Cache-Control': 'public, max-age=31536000, immutable' } });
    }
    if (path.startsWith('/api/v1/')) {
      try { return await handleApi(request, env, url); }
      catch (e) { return json({ ok: false, data: null, error: { code: 'worker_error', message: String(e && e.message || e) } }, 500); }
    }
    if (path === '/mcp') {
      try { return await handleMcp(request, env); }
      catch (e) { return json({ ok: false, data: null, error: { code: 'worker_error', message: String(e && e.message || e) } }, 500); }
    }
    if (path === '/' || path === '/index.html') {
      return new Response(APP_HTML, { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' } });
    }
    return fail('not_found', '页面不存在: ' + path, 404);
  },
};
